using System;
using System.Collections.Generic;
using UnityEngine;

namespace MobileIdleBuilder
{
    /// <summary>
    /// The 3D structure of every molecule's belt visual: ball-and-stick models from
    /// <c>Resources/BeltMolecules.json</c>, generated by <c>scripts/belt_items/build_molecules.py</c> (PubChem
    /// conformers, plus inline structures for ionic / inorganic items). Approved 2026-11-18 from the Blender mockup
    /// <c>scripts/belt_items/mockup_molecules.py</c>, which applies the same sizing rule as <see cref="BuildMesh"/>.
    /// </summary>
    public static class BeltMoleculeData
    {
        // Sizing rule (keep in step with mockup_molecules.py).
        public const float Ball        = 0.6f;    // atom ball radius = element radius x Ball (Angstrom)
        public const float Bond        = 0.11f;   // bond tube radius (Angstrom); x1.35 for double / triple bonds
        public const float ChunkBall   = 1.35f;   // hide-H molecules: thicker so the skeleton reads
        public const float ChunkBond   = 1.6f;
        public const float MaxScale    = 0.1f;    // tiles per Angstrom for small molecules
        public const float FitRadius   = 0.17f;   // the whole model fits in this radius (item diameter 0.36)
        /// <summary>A fixed tilt so flat molecules aren't seen edge-on before they start tumbling.</summary>
        public static readonly Quaternion Tilt = Quaternion.Euler(20f, 0f, 10f);

        [Serializable] private class Element  { public string symbol; public string color; public float radius; }
        [Serializable] private class Atom     { public string e; public float x, y, z; }
        [Serializable] private class BondDef  { public int a, b, o; }
        [Serializable] private class Molecule { public string id; public bool hideH; public Atom[] atoms; public BondDef[] bonds; }
        [Serializable] private class File     { public Element[] elements; public Molecule[] molecules; }

        private static Dictionary<string, Molecule> s_Molecules;
        private static Dictionary<string, (Color color, float radius)> s_Elements;

        /// <summary>The molecule ids with a structure (loads the data on first use).</summary>
        public static IEnumerable<string> Ids { get { Load(); return s_Molecules.Keys; } }

        public static bool Has(string itemId) { Load(); return itemId != null && s_Molecules.ContainsKey(itemId); }

        private static void Load()
        {
            if (s_Molecules != null) return;
            s_Molecules = new Dictionary<string, Molecule>();
            s_Elements  = new Dictionary<string, (Color, float)>();
            var asset = Resources.Load<TextAsset>("BeltMolecules");
            if (asset == null)
            {
                GameLogger.Warning("[BeltMoleculeData] Resources/BeltMolecules.json missing; molecules keep their icon tiles.");
                return;
            }
            var file = JsonUtility.FromJson<File>(asset.text);
            foreach (var e in file.elements ?? Array.Empty<Element>())
                s_Elements[e.symbol] = (ColorUtility.TryParseHtmlString("#" + e.color, out var c) ? c : Color.magenta, e.radius);
            foreach (var m in file.molecules ?? Array.Empty<Molecule>())
                s_Molecules[m.id] = m;
        }

        /// <summary>
        /// One mesh for the molecule: a sphere per atom and a two-coloured tube per bond (each half in its atom's
        /// colour), tilted by <see cref="Tilt"/> and scaled to fit the belt item. <paramref name="toShaderSpace"/>
        /// converts the vertex colours (the project is linear; mesh colours skip that conversion). Null when unknown.
        /// </summary>
        public static Mesh BuildMesh(string itemId, Func<Color, Color> toShaderSpace)
        {
            Load();
            if (itemId == null || !s_Molecules.TryGetValue(itemId, out var mol)) return null;

            // Atoms kept (hide-H molecules drop their hydrogens) and the old -> new index map for bonds.
            var keep = new List<int>();
            var index = new int[mol.atoms.Length];
            for (int i = 0; i < mol.atoms.Length; i++)
            {
                index[i] = -1;
                if (mol.hideH && mol.atoms[i].e == "H") continue;
                index[i] = keep.Count;
                keep.Add(i);
            }
            float chunkBall = mol.hideH ? ChunkBall : 1f, chunkBond = mol.hideH ? ChunkBond : 1f;

            var pos = new Vector3[keep.Count];
            var rad = new float[keep.Count];
            var col = new Color[keep.Count];
            float extent = 0f;
            for (int k = 0; k < keep.Count; k++)
            {
                var a = mol.atoms[keep[k]];
                var (c, r) = s_Elements.TryGetValue(a.e, out var el) ? el : (Color.magenta, 0.7f);
                pos[k] = Tilt * new Vector3(a.x, a.y, a.z);
                rad[k] = r * Ball * chunkBall;
                col[k] = toShaderSpace(c);
                extent = Mathf.Max(extent, pos[k].magnitude + rad[k]);
            }
            float scale = extent > 0f ? Mathf.Min(MaxScale, FitRadius / extent) : MaxScale;

            var b = new BeltParticleMeshes.Builder();
            for (int k = 0; k < keep.Count; k++)
                b.Sphere(pos[k] * scale, rad[k] * scale, col[k], k % 5 + 1, 10, 6);
            foreach (var bond in mol.bonds ?? Array.Empty<BondDef>())
            {
                int i = bond.a >= 0 && bond.a < index.Length ? index[bond.a] : -1;
                int j = bond.b >= 0 && bond.b < index.Length ? index[bond.b] : -1;
                if (i < 0 || j < 0) continue;
                float br = Bond * chunkBond * (bond.o >= 2 ? 1.35f : 1f) * scale;
                Vector3 pi = pos[i] * scale, pj = pos[j] * scale, mid = (pi + pj) * 0.5f;
                // Each half shakes with its own atom, so a vibrating bond stays attached at both ends.
                float si = i % 5 + 1, sj = j % 5 + 1;
                b.Tube(pi, mid, br, col[i], si, sj, 0f, 0.5f, 6);
                b.Tube(mid, pj, br, col[j], si, sj, 0.5f, 1f, 6);
            }
            return b.ToMesh($"Molecule_{itemId}");
        }
    }
}
